:root { --p05-col: 52rem; --p05-area-min: clamp(8rem, 38cqh, 18rem); --p05-room: 2rem; --p05-combo-room: 3.25rem; --p05-tab-end: 1.5rem; --p05-menu-min: 10rem; --p05-menu-rest: 7rem; }
.p05-wrap { max-width: var(--p05-col); margin-inline: auto; display: grid; gap: var(--s-3); margin-top: calc(var(--p05-scroll, 0rem) * -1); }
.p05-top { display: grid; gap: var(--s-2); }
.p05-form { display: grid; gap: var(--s-4); }
.p05-form .field__head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: flex-start; column-gap: var(--s-2); }
.p05-pos { position: relative; }
.p05-ph { color: var(--muted); }
.p05-form .select[aria-invalid="true"] { border-color: var(--terra); outline: var(--w1) solid var(--terra); outline-offset: calc(var(--w1) * -2); }
.p05-form .select.p05-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -2); }
.p05-combo { position: relative; }
.p05-combo .textarea { padding-inline-end: var(--p05-combo-room); }
.p05-combo__btn { position: absolute; inset-block-start: 0; inset-inline-end: var(--w2); }
.p05-name { min-height: var(--ctl-h); resize: none; field-sizing: content; }
.p05-area { position: relative; }
.p05-area .textarea { min-height: var(--p05-area-min); resize: none; }
.field__count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.p05-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -2); }
.p05-e { --frame-w: var(--w2); }
.p05-ro { display: grid; }
.rec.p05-roc { grid-template-columns: minmax(0, 1fr); grid-template-areas: "body"; padding-inline: 0; border-top: var(--w1) solid var(--rule); }
.p05-actions { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--s-2); }
.p05-actions > .btn { flex: 1 1 0; }
.p05-actions--3 { display: grid; gap: var(--s-3); }
.p05-main { display: flex; gap: var(--s-2); }
.p05-main > * { flex: 1 1 0; }
@media (min-width: 48rem) and (min-height: 31.25rem) {
  .p05-actions > .btn { flex: none; }
  .p05-actions--3 { grid-template-columns: 1fr auto 1fr; align-items: center; }
  .p05-actions--3 > .p05-del { justify-self: start; }
  .p05-main > * { flex: none; }
}
.p05-tipwrap { display: flex; justify-content: center; }
.p05-actions .btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p05-deleted { display: grid; justify-items: center; gap: var(--s-3); padding: var(--s-4) 0; }
.p05-deleted .banner { width: 100%; justify-content: center; text-align: center; }
.p05-app .tabwrap > .tab { padding-inline: var(--s-1) var(--p05-tab-end); }
.p05-app .tab__help { inset-inline-end: var(--w2); }
.dialog__foot.p05-foot { flex-direction: column; }
.p05-foot > * { flex: none; }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
.app--kbd .p05-actions { position: sticky; bottom: 0; z-index: 1; background: var(--white); padding: var(--s-2) var(--s-3); margin-inline: calc(var(--s-3) * -1); border-top: var(--w1) solid var(--rule); }
